"""Textures generated by the repo's own code (texgen.py)."""
import numpy as np

from brmap import texgen


def test_clock_face_is_upright():
    # the 12 o'clock double bar is darker than the 6 o'clock single bar, so 12 is at the top:
    # the mean of 8 rows by 40 columns across the hour bars, top centre against bottom centre
    img = texgen.clock_face()
    assert (img.mode, img.size) == ("RGBA", (512, 512))
    grey = np.asarray(img.convert("L"), float)
    s, c = img.width, img.width // 2
    row = round(s * (0.5 - texgen.BAR_MID))          # the middle of the 12 o'clock bars
    top = grey[row - 4:row + 4, c - 20:c + 20].mean()
    bottom = grey[s - row - 4:s - row + 4, c - 20:c + 20].mean()
    assert top < bottom - 40


def test_clock_face_is_a_cream_dial_in_a_stone_square():
    # opaque all over: with the material's alpha test off, a clear corner would render black
    img = texgen.clock_face(256)
    rgba = np.asarray(img)
    assert img.size == (256, 256)
    assert (rgba[..., 3] == 255).all()                                   # every pixel is opaque
    corners = rgba[[0, 0, -1, -1], [0, -1, 0, -1], :3].astype(int)
    assert (abs(corners - (226, 218, 200)) <= 6).all()                   # the stone around the dial
    r, g, b, a = rgba[96, 128]                                           # inside the dial, above the hub
    assert min(r, g, b) > 180 and r >= b                                 # cream
    ring = rgba[3:20, 128, :3].astype(int).sum(axis=1).min()             # the dark ring at the top
    assert ring < 200
    assert texgen.clock_face(256).tobytes() == img.tobytes()             # deterministic


def test_bevel_normal_convention():
    img = texgen.bevel_normal()
    assert (img.mode, img.size) == ("RGB", (256, 256))
    n = np.asarray(img, float)
    mid = slice(112, 144)                                                # away from the corners
    left, right = n[mid, 2:12, 0].mean(), n[mid, -12:-2, 0].mean()
    top, bottom = n[2:12, mid, 1].mean(), n[-12:-2, mid, 1].mean()
    assert left < 128 < right                                            # +X points right
    if texgen.NORMAL_CONVENTION == "opengl":
        assert top > 128 > bottom                                        # +Y points up
    else:
        assert texgen.NORMAL_CONVENTION == "directx" and top < 128 < bottom
    centre = n[120:136, 120:136].mean(axis=(0, 1))
    assert np.allclose(centre, [128, 128, 255], atol=2)                  # the flat top faces out


def test_bevel_normal_vectors_are_unit_length():
    n = np.asarray(texgen.bevel_normal(64), float) / 255 * 2 - 1
    assert np.allclose(np.linalg.norm(n, axis=2), 1, atol=0.02)
    assert (n[..., 2] > 0).all()


# ------------------------------------------------------------------ the styled buildings' facades

def styled_styles() -> dict:
    from brmap import styled
    return styled.load_registry()["styles"]


def test_facade_styles_exist():
    # every style of styled.yaml has its wall drawn by texgen.facade: square, a power of two, deterministic
    from PIL import Image

    styles = styled_styles()
    assert {"lsu", "ribbon_dark", "precast_punched", "brick_hotel", "precast_arena", "glass_blue"} <= set(styles)
    for style in styles:
        out = texgen.facade(style, size=128)
        maps = {k: v for k, v in out.items() if isinstance(v, Image.Image)}
        assert {"b", "r"} <= set(maps), style
        for key, img in maps.items():
            w, h = img.size
            assert w == h == 128 and w & (w - 1) == 0, (style, key, img.size)
        assert maps["b"].mode == "RGB" and maps["r"].mode == "L", style
        assert set(out) - set(maps) <= {"m"}, style                    # the one factor: metallic
        assert 0.0 <= out.get("m", 0.0) <= 1.0, style
        assert texgen.facade(style, size=128)["b"].tobytes() == maps["b"].tobytes(), style
    assert texgen.facade("glass_blue")["m"] > 0.0                       # glass reflects
    assert "m" not in texgen.facade("precast_punched")


def test_facade_floor_lines():
    # the window rows of precast_punched repeat once a floor: the autocorrelation of the rows' brightness
    # peaks at size / floors_per_tile px
    size = 512
    floors = texgen.FACADES["precast_punched"]["floors"]
    assert floors > 1 and size % floors == 0
    grey = np.asarray(texgen.facade("precast_punched", size=size)["b"].convert("L"), float)
    rows = grey.mean(axis=1) - grey.mean()
    spectrum = np.fft.rfft(rows)
    auto = np.fft.irfft(spectrum * np.conj(spectrum), n=size)       # circular autocorrelation
    lag = int(np.argmax(auto[8:size // 2 + 1])) + 8                 # the first lags are the rows' own width
    assert lag == size // floors
    assert auto[size // floors] > 0.8 * auto[0]


def test_facade_windows_are_darker_and_smoother_than_the_wall():
    for style in ("ribbon_dark", "precast_punched", "brick_hotel", "glass_blue"):
        maps = texgen.facade(style, size=256)
        b = np.asarray(maps["b"].convert("L"), float).ravel()
        r = np.asarray(maps["r"], float).ravel()
        dark = b < np.percentile(b, 20)                           # the glass
        light = b > np.percentile(b, 80)
        assert r[dark].mean() < r[light].mean() - 40, style       # glass is smooth, cladding rough


def test_gothic_window_is_cut_out_round_its_arch():
    img = texgen.gothic_window(128)
    rgba = np.asarray(img, float)
    assert (img.mode, img.size) == ("RGBA", (128, 128))
    assert (rgba[[0, 0, 10], [0, -1, 10], 3] == 0).all()                   # clear beside the arch's head
    assert rgba[-2, 64, 3] == 255 and rgba[5, 64, 3] == 255                 # the foot and the apex are solid
    assert (rgba[..., 3] > 0).mean() > 0.8
    clear = rgba[..., 3] == 0
    assert np.allclose(rgba[clear][:, :3], texgen.GOTHIC_STONE, atol=1)     # no dark fringe in the mipmaps
    glass = rgba[80, 40, :3]                                                # in the left lancet
    assert glass.sum() < sum(texgen.GOTHIC_STONE) - 300
    assert texgen.gothic_window(128).tobytes() == img.tobytes()


# ------------------------------------------------------------------ Spanish moss

def test_moss_card_alpha_and_colour():
    m = texgen.moss_card(seed=1)
    a = np.asarray(m["o"].convert("L")) / 255
    assert 0.15 <= (a > 0.5).mean() <= 0.45
    rgb = np.asarray(m["b"].convert("RGB"))[a > 0.5]
    assert rgb.min() >= 0x60 and rgb.max() <= 0xB0


def test_moss_card_colours():
    """Grey-green, not the near white it read as in game (the old range, #8F9682 .. #BFC4AE, lit up pale)."""
    lo, hi = np.array((0x6F, 0x78, 0x65)), np.array((0xA2, 0xA8, 0x94))
    for seed in (0, 1, 2):
        m = texgen.moss_card(seed=seed)
        mean = np.asarray(m["b"].convert("RGB"), float)[np.asarray(m["o"]) > 127].mean(axis=0)
        assert (lo <= mean).all() and (mean <= hi).all(), (seed, mean)
        assert mean[1] > mean[0] > mean[2]                              # green over red over blue


def test_moss_card_maps():
    m = texgen.moss_card(seed=1)
    assert set(m) == {"b", "o", "nm"}
    assert {k: (img.mode, img.size) for k, img in m.items()} == {
        "b": ("RGB", (512, 1024)), "o": ("L", (512, 1024)), "nm": ("RGB", (512, 1024))}
    assert texgen.moss_card(seed=1)["o"].tobytes() == m["o"].tobytes()          # deterministic
    assert texgen.moss_card(seed=2)["o"].tobytes() != m["o"].tobytes()
    # every pixel, stroke or not, is a grey-green between the two ends (no dark fringe in the mipmaps)
    rgb = np.asarray(m["b"], int).reshape(-1, 3)
    lo, hi = np.array(texgen.MOSS_COLOURS[0]), np.array(texgen.MOSS_COLOURS[1])
    assert (rgb >= lo - 1).all() and (rgb <= hi + 1).all()
    assert texgen.MOSS_COLOURS == ((0x6F, 0x78, 0x65), (0xA2, 0xA8, 0x94))


def test_moss_card_hangs_from_the_top():
    # filaments hang down: denser at the top than half way down, thinning out toward the foot; mostly vertical
    a = np.asarray(texgen.moss_card(seed=3)["o"], float) / 255
    rows = (a > 0.5).mean(axis=1)
    top, middle, foot = rows[:200].mean(), rows[400:600].mean(), rows[-120:].mean()
    assert top > 1.3 * middle and middle > foot
    gy, gx = np.gradient(a)
    assert np.abs(gx).sum() > 1.5 * np.abs(gy).sum()               # edges run up and down


def test_moss_card_normal_map():
    m = texgen.moss_card(seed=1)
    n = np.asarray(m["nm"], float) / 255 * 2 - 1
    assert np.allclose(np.linalg.norm(n, axis=2), 1, atol=0.03) and (n[..., 2] > 0).all()
    from scipy import ndimage

    a = np.asarray(m["o"], float) / 255
    tilt = np.hypot(n[..., 0], n[..., 1])
    clear = ndimage.maximum_filter(a, size=13) == 0                 # 6 px or more from any stroke
    assert clear.sum() > 1000 and tilt[clear].max() < 0.02           # flat there
    assert tilt[a > 0].max() > 0.3                                   # the strokes stand out
